const canvas=document.querySelector('#paint'),ctx=canvas.getContext('2d');
const wall=document.createElement('canvas'),wc=wall.getContext('2d');
const coat=document.createElement('canvas'),cc=coat.getContext('2d');
const mask=document.createElement('canvas'),mc=mask.getContext('2d',{willReadFrequently:true});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let w,h,dpr,base,left,width,floor,drips=[],brushes=[],last=null,opening=false;
let randSeed=27;function random(){randSeed=(randSeed*1664525+1013904223)>>>0;return randSeed/4294967296;}
function resize(){w=innerWidth;h=innerHeight;dpr=Math.min(devicePixelRatio||1,2);for(const c of [canvas,wall,coat,mask]){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}for(const c of [ctx,wc,cc,mc])c.setTransform(dpr,0,0,dpr,0,0);floor=h-(w<600?34:46);base=h*.55;left=w*.05;width=w*.87;randSeed=27;
wc.fillStyle='#a9aaa3';wc.fillRect(0,0,w,h);
// A cached mottled plaster surface, with pores and irregular hairline marks.
for(let i=0;i<350;i++){let x=random()*w,y=random()*h,r=30+random()*150,g=wc.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,random()>.5?'rgba(232,229,214,.09)':'rgba(54,58,53,.075)');g.addColorStop(1,'transparent');wc.fillStyle=g;wc.fillRect(x-r,y-r,r*2,r*2);}
for(let i=0;i<Math.min(w*h/14,80000);i++){wc.fillStyle=random()>.5?'rgba(249,244,228,.16)':'rgba(34,37,33,.12)';const r=random()*1.3+.2;wc.fillRect(random()*w,random()*h,r,r);}
for(let i=0;i<22;i++){let x=random()*w,y=random()*h;wc.beginPath();wc.moveTo(x,y);for(let j=0;j<6;j++){x+=(random()-.4)*36;y+=random()*18;wc.lineTo(x,y);}wc.strokeStyle='rgba(60,62,56,.10)';wc.lineWidth=.4+random()*.6;wc.stroke();}
const shade=wc.createLinearGradient(0,0,w,h);shade.addColorStop(0,'rgba(255,255,240,.16)');shade.addColorStop(1,'rgba(20,24,20,.12)');wc.fillStyle=shade;wc.fillRect(0,0,w,h);
mc.font=`900 ${w*.255}px Impact,'Arial Black',sans-serif`;const scale=width/mc.measureText('FRANCO').width;mc.save();mc.translate(left,base);mc.transform(scale,0,-.13,1,0,0);mc.fillText('FRANCO',0,0);mc.restore();drips=[];
for(let i=0;i<44;i++){let x=left+width*(i+.4)/44;if(mc.getImageData(Math.round(x*dpr),Math.round((base-4)*dpr),1,1).data[3]>100)drips.push({x,width:1.4+random()*3,len:35+random()*(floor-base-55),phase:random()*7,speed:.05+random()*.14,long:random()>.84});}brushes=[];last=null;}
function draw(now){if(document.hidden||document.querySelector('#stage').hidden){requestAnimationFrame(draw);return;}ctx.drawImage(wall,0,0,w,h);cc.globalCompositeOperation='source-over';cc.fillStyle='#f5f4ef';cc.fillRect(0,0,w,h);cc.globalCompositeOperation='destination-out';brushes=brushes.filter(b=>now-b.t<4200);
for(const b of brushes){const age=(now-b.t)/4200,alpha=Math.min(1,(1-age)*2.5),radius=w<600?72:110;const g=cc.createRadialGradient(b.x,b.y,0,b.x,b.y,radius);g.addColorStop(0,`rgba(0,0,0,${alpha*.8})`);g.addColorStop(.45,`rgba(0,0,0,${alpha*.55})`);g.addColorStop(1,'rgba(0,0,0,0)');cc.fillStyle=g;cc.fillRect(b.x-radius,b.y-radius,2*radius,2*radius);cc.fillStyle=`rgba(0,0,0,${alpha*.22})`;for(let j=0;j<22;j++){const a=j*2.399,r=radius*Math.sqrt((j+.5)/22);cc.fillRect(b.x+Math.cos(a)*r,b.y+Math.sin(a)*r,1.5,1.5);}}
cc.globalCompositeOperation='source-over';ctx.drawImage(coat,0,0,w,h);ctx.fillStyle='#101110';ctx.drawImage(mask,0,0,w,h);
const t=reduced?0:now/1000;for(const d of drips){const max=floor-base,cycle=(t*d.speed+d.phase)%1,len=d.long?max:Math.min(max,d.len*(.85+.15*Math.sin(t*.24+d.phase)));const end=d.long?base+cycle*max:base+len;ctx.beginPath();ctx.moveTo(d.x-d.width,base-6);ctx.bezierCurveTo(d.x-d.width*.6,base+len*.35,d.x-d.width*.5,end-10,d.x-d.width*.8,end-4);ctx.quadraticCurveTo(d.x,end+5,d.x+d.width*.8,end-4);ctx.bezierCurveTo(d.x+d.width*.3,end-14,d.x+d.width*.5,base+20,d.x+d.width,base-6);ctx.fill();if(d.long){ctx.beginPath();ctx.ellipse(d.x,end+9,d.width*.65,d.width*1.4,0,0,Math.PI*2);ctx.fill();}}
// The paint pool meets the mouse-hole cut at the same floor level.
ctx.beginPath();ctx.moveTo(0,floor);for(let x=0;x<=w+16;x+=16){const ripple=Math.sin(x*.024)*1.5+Math.sin(x*.073)*.7;ctx.lineTo(x,floor+ripple);}ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(220,224,211,.1)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(w*.08,floor+8);ctx.bezierCurveTo(w*.3,floor+3,w*.47,floor+13,w*.62,floor+6);ctx.stroke();requestAnimationFrame(draw);}
function spray(e){if(opening)return;const p={x:e.clientX,y:e.clientY,t:performance.now()};if(last){const length=Math.hypot(p.x-last.x,p.y-last.y),steps=Math.min(20,Math.ceil(length/18));for(let i=1;i<steps;i++)brushes.push({x:last.x+(p.x-last.x)*i/steps,y:last.y+(p.y-last.y)*i/steps,t:p.t});}brushes.push(p);if(brushes.length>200)brushes.splice(0,brushes.length-200);last=p;}
canvas.addEventListener('pointermove',spray);canvas.addEventListener('pointerdown',spray);canvas.addEventListener('pointerleave',()=>last=null);addEventListener('resize',resize);resize();requestAnimationFrame(draw);
const stage=document.querySelector('#stage'),world=document.querySelector('#world'),inside=document.querySelector('#inside'),entry=document.querySelector('#enter');
entry.addEventListener('click',()=>{if(opening)return;opening=true;const r=entry.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height*.55;world.style.transformOrigin=`${x}px ${y}px`;const scale=Math.max(w/r.width,h/r.height)*3;world.style.transform=`translate(${w/2-x}px,${h/2-y}px) scale(${scale})`;setTimeout(()=>{stage.hidden=true;inside.hidden=false;document.querySelector('#back').focus();},reduced?0:1700);});
document.querySelector('#back').addEventListener('click',()=>{inside.hidden=true;world.style.transition='none';world.style.transform='none';stage.hidden=false;void world.offsetWidth;world.style.transition='';opening=false;entry.focus();});
